  @{
    @d k m n S @.  @d k F @.  @d k m ph @.
    cxpfdcvg.1 @e |- F = ( k e. NN0 |-> ( n e. NN0 |-> sum_ m e. ( 0 ... k )
      ( ( ( -u 1 ^ m ) x. ( k _C m ) ) x. ( ( n + m ) ^c S ) ) ) @.
    @( FIX COMMENT @)
    cxpfdfval @p |- ( K e. NN0 -> ( F ` K ) = ( n e. NN0 |-> sum_ m e.
    ( 0 ... K ) ( ( ( -u 1 ^ m ) x. ( K _C m ) ) x. ( ( n + m ) ^c S ) ) ) ) @=
      ? @.
      @( [18-Jul-2014] @)

    @( FIX COMMENT @)
    cxpfdval @p |- ( ( K e. NN0 /\ N e. NN0 ) -> ( ( F ` K ) ` N ) = sum_ m e.
      ( 0 ... K ) ( ( ( -u 1 ^ m ) x. ( K _C m ) ) x. ( ( N + m ) ^c S ) ) ) @=
      ? @.
      @( [18-Jul-2014] @)

    @( FIX COMMENT @)
    cxpfd0 @p |- ( N e. NN0 -> ( ( F ` 0 ) ` N ) = ( N ^c S ) ) @=
      ? @.
      @( [18-Jul-2014] @)

    cxpfdcvg.2 @e |- ( ph -> K e. NN0 ) @.
    cxpfdcvg.3 @e |- ( ph -> S e. RR ) @.
    @( FIX COMMENT @)
    cxpfddif @p |- ( ph -> ( ( F ` ( K + 1 ) ) ` N ) =
      ( ( ( F ` K ) ` N ) - ( ( F ` K ) ` ( N + 1 ) ) ) ) @=
      ? @.
      @( [18-Jul-2014] @)

    @( FIX COMMENT @)
    cxpfditg @p |- ( ph -> ( ( F ` K ) ` N ) = sum_ m e. ( 0 ... N )
      ( ( ( -u 1 ^ m ) x. ( K _C m ) ) x. ( ( N + m ) ^c S ) ) ) @=
      ? @.
      @( [18-Jul-2014] @)

    cxpfdcvg.4 @e |- ( ph -> S < N ) @.
    @{
      cxpfdle.5 @e |- ( ph -> K e. NN0 ) @.
      cxpfdle.6 @e |- ( ph -> M e. ( ZZ>= ` K ) ) @.
      @( FIX COMMENT @)
      cxpfdle @p |- ( ph -> ( F ` M ) <_ ( F ` K ) ) @=
